			function getSrvyResult(){

			    var dmSearch = app.lookup("dmSearch");
			    var dsQustnbKnd = app.lookup("dsQustnbKnd");
			    var dsSrvyParam = app.lookup("dsSrvyParam");
			    
			    dmSearch.setValue("CASE_MNG_NO", caseMngNo);
			    dmSearch.setValue("CASE_MNG_ODRNO", caseMngOdrno);
			    
			    if (untTaskwk == "U04") { //쉼터
			        dsSrvyParam.setValue(0, "QUSTNB_TMPT_MNG_NO", dsQustnbKnd.getValue(0, "ADDTNG_MNG_VALUE1"));
			    } else {
			        dsSrvyParam.setValue(0, "QUSTNB_TMPT_MNG_NO", dsQustnbKnd.getValue(1, "ADDTNG_MNG_VALUE1"));
			        dsSrvyParam.setValue(1, "QUSTNB_TMPT_MNG_NO", dsQustnbKnd.getValue(0, "ADDTNG_MNG_VALUE2"));
			    }
			    
			    util.Submit.send(app, "subList3", function(pbSuccess) {
			        if (pbSuccess) {

			            var dsSrvyDgstfn = app.lookup("dsSrvyDgstfn");
			            if (dsSrvyDgstfn.getRowCount() > 0) {
			                var RcptSum = ValueUtil.fixNumber(0);       //총합
			                for (var i = 0; i < 4; i++) {
			                    var rspnsValue = dsSrvyDgstfn.getValue(i, "QESITM_SINGL_RSPNS_VALUE");
			                    RcptSum += ValueUtil.fixNumber(rspnsValue);
			                }
			    
			                var OfrSum = ValueUtil.fixNumber(0);       //총합
			                for (var i = 5; i < 8; i++) {
			                    var rspnsValue = dsSrvyDgstfn.getValue(i, "QESITM_SINGL_RSPNS_VALUE");
			                    OfrSum += ValueUtil.fixNumber(rspnsValue);
			                }
			                    
			                app.lookup("optRcptSum").value = RcptSum;
			                app.lookup("optOfrSum").value = OfrSum;
			                app.lookup("optRcptOpnn").value = dsSrvyDgstfn.getValue(4, "QESITM_RSPNS_CN");
			                app.lookup("optOfrOpnn").value = dsSrvyDgstfn.getValue(8, "QESITM_RSPNS_CN");
			                app.lookup("optGnrlsOpnn").value = dsSrvyDgstfn.getValue(9, "QESITM_RSPNS_CN");
			            }
			            var dsList = app.lookup("dsList");
			            // 
			            if (ValueUtil.isNull(dsSrvyDgstfn.getValue(0, "QESITM_SINGL_RSPNS_VALUE"))) {
			                if (ValueUtil.isNull(dsList.getValue(0, "DGSTFN_EXMN_YMD"))) {
			                    dsList.setValue(0, "DGSTFN_EXMN_YMD", sToday);
			                }
			            }
			        }
			            
			        util.Control.redraw(app, "grpData");
			                
			    });
			}

