			function chkVal(){
			    var cmbPstrtrResdn = app.lookup("cmbPstrtrResdn1").value;
			    if(ValueUtil.isNull(cmbPstrtrResdn)){
			        util.Msg.alert(app, "퇴소후 거주현황은 필수입니다.");
			        return false;
			    }
			    if(cmbPstrtrResdn == "99"){
			        if(ValueUtil.isNull(app.lookup("ipbPstrtrResdnEtc").value)){
			            util.Msg.alert(app, "퇴소후 거주현황 기타내용은 필수입니다.");
			            app.lookup("ipbPstrtrResdnEtc").focus();
			            return false;
			        }
			    }
			    var rdbPstrtrSchulw = app.lookup("rdbPstrtrSchulw").value;
			    if(ValueUtil.isNull(rdbPstrtrSchulw)){
			        util.Msg.alert(app, "퇴소후 학업현황은 필수입니다.");
			        return false;
			    }
			    if(rdbPstrtrSchulw == "99"){
			        if(ValueUtil.isNull(app.lookup("ipbPstrtrSchulwEtc").value)){
			            util.Msg.alert(app, "퇴소후 학업현황 기타내용은 필수입니다.");
			            app.lookup("ipbPstrtrSchulwEtc").focus();
			            return false;
			        }
			    }
			    var rdbPstrtrSlfrl = app.lookup("rdbPstrtrSlfrl").value;
			    if(ValueUtil.isNull(rdbPstrtrSlfrl)){
			        util.Msg.alert(app, "퇴소후 자립현황은 필수입니다.");
			        return false;
			    }
			    
			    if(rdbPstrtrSlfrl == "99"){
			        if(ValueUtil.isNull(app.lookup("ipbPstrtrSlfrl").value)){
			            util.Msg.alert(app, "퇴소후 자립현황 기타내용은 필수입니다.");
			            app.lookup("ipbPstrtrSlfrl").focus();
			            return false;
			        }
			    } else if (rdbPstrtrSlfrl == "02") {
			        if(ValueUtil.isNull(app.lookup("cmbPstrtrSubSlfrl").value)){
			            util.Msg.alert(app, "퇴소후 자립현황 취업유형은 필수입니다.");
			            app.lookup("cmbPstrtrSubSlfrl").focus();
			            return false;
			        }
			    }
			    
			    if (!util.validate(app, "grdList")) return false;
			    
			    //for 설문대상자(SBB110)
			    var dsList2 = app.lookup("dsList2");
			    dsList2.addRow();
			    dsList2.setValue(0, "CASE_MNG_NO", caseMngNo);
			    dsList2.setValue(0, "CASE_MNG_ODRNO", caseMngOdrno);
			    
			    return true;
			}
